package dev.codex.schubert.nk.batch.file;

import dev.codex.schubert.nk.storage.DirectoryCalls;
import dev.codex.schubert.nk.storage.InodeSecurityCalls;
import dev.codex.schubert.nk.storage.LinuxDirectoryCalls;
import dev.codex.schubert.nk.storage.LinuxFileLock;
import dev.codex.schubert.nk.storage.LinuxHostDirectoryCalls;
import dev.codex.schubert.nk.storage.LinuxInodeSecurity;
import dev.codex.schubert.nk.storage.ResourceScope;
import dev.codex.schubert.nk.storage.StorageIoException;
import edu.umd.cs.findbugs.annotations.SuppressFBWarnings;
import edu.umd.cs.findbugs.annotations.SuppressMatchType;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Map;
import java.util.Objects;
import java.util.Optional;
import org.jspecify.annotations.NullMarked;
import org.jspecify.annotations.Nullable;

/**
 * Root-only, read-only A admission in host and service mount views; never maintenance M.
 * NK-OPS-001; SYS-002/004,OPS-009; UI212/251; SS341/342/343; SSC086/087; PG294;
 * PT-OPS-ADMISSIONLOCK-001..008. Caller first authenticates kernel proc/PID1/system manager/boot
 * and its fixed Unit identity; rechecks that identity after A and before exec. This adapter does
 * not issue a permit or attest those identities. Trusted callback borrows A only until return or
 * same-PID native exec; all retained root/entry capabilities are CLOEXEC and never exported.
 */
@NullMarked
public final class StartupAdmissionFile {
  private static final int MINIMUM_PRIVATE_VIEW_CAPACITY = 1;

  private final Path runtime;
  private final DirectoryCalls host;
  private final DirectoryCalls service;
  private final InodeSecurityCalls security;
  private final LinuxFileLock locks;
  private final Io io;

  interface Io {
    @Nullable Map<String, Object> attributes(Path held) throws IOException;

    @Nullable String filesystemType(Path held) throws IOException;
  }

  // Fixed /run, exact portability review only. No security/null/coverage exclusion.
  @SuppressFBWarnings(
      value = "DMI_HARDCODED_ABSOLUTE_FILENAME",
      matchType = SuppressMatchType.EXACT,
      justification = "SS341/343/SSC086 fixed /run A; PG294/PT-OPS-ADMISSIONLOCK-008")
  public static StartupAdmissionFile create() {
    return new StartupAdmissionFile(
        Path.of("/run"),
        LinuxHostDirectoryCalls.create(),
        LinuxDirectoryCalls.create(),
        LinuxInodeSecurity.create(),
        LinuxFileLock.create(),
        new NioIo());
  }

  StartupAdmissionFile(
      Path runtime,
      DirectoryCalls host,
      DirectoryCalls service,
      InodeSecurityCalls security,
      LinuxFileLock locks,
      Io io) {
    this.runtime = Objects.requireNonNull(runtime, "runtime");
    this.host = Objects.requireNonNull(host, "host view");
    this.service = Objects.requireNonNull(service, "service view");
    this.security = Objects.requireNonNull(security, "security");
    this.locks = Objects.requireNonNull(locks, "locks");
    this.io = Objects.requireNonNull(io, "io");
    if (!runtime.isAbsolute()
        || runtime.getNameCount() == 0
        || !runtime.equals(runtime.normalize()))
      throw new IllegalArgumentException("invalid startup runtime");
  }

  public <T> Optional<T> tryExclusive(LinuxFileLock.StartupOperation<T> operation)
      throws StorageIoException {
    Objects.requireNonNull(operation, "startup operation");
    return tryExclusiveObserved(admission -> operation.execute(admission.descriptor()));
  }

  /** Actual admitted held A identity, borrowed only while this owner's native OFD lock lives. */
  public record Admission(int descriptor, long device, long inode) {}

  @FunctionalInterface
  public interface AdmittedOperation<T> {
    T execute(Admission admission) throws IOException;
  }

  public <T> Optional<T> tryExclusiveObserved(AdmittedOperation<T> operation)
      throws StorageIoException {
    Objects.requireNonNull(operation, "startup operation");
    require(security.effectiveUid() == 0);
    try {
      return withView(
          host,
          true,
          (hostSnapshot, hostFile, hostOwner) ->
              withView(
                  service,
                  false,
                  (serviceSnapshot, serviceFile, serviceOwner) -> {
                    require(hostSnapshot.equals(serviceSnapshot));
                    return locks.tryExclusiveForStartup(
                        hostFile,
                        reserved -> {
                          verify(hostSnapshot);
                          // A fresh private-view open has a different OFD and must contend with
                          // host A.
                          require(locks.tryExclusive(serviceFile, () -> Boolean.TRUE).isEmpty());
                          // BUG265/YKT199: consume every root/entry observation owner before a
                          // callback may replace this root JVM. Only the A lock owner survives.
                          serviceOwner.close();
                          hostOwner.close();
                          T result =
                              operation.execute(
                                  new Admission(
                                      reserved,
                                      hostSnapshot.file().device(),
                                      hostSnapshot.file().inode()));
                          verify(hostSnapshot);
                          return result;
                        });
                  }));
    } catch (IOException failure) {
      throw unavailable();
    }
  }

  private <T> T withView(DirectoryCalls calls, boolean hostView, ViewOperation<T> operation)
      throws IOException {
    return ResourceScope.<ViewOwner, T, StorageIoException>acquire(
        () -> new ViewOwner(calls, Math.addExact(runtime.getNameCount(), 3)),
        ViewOwner::close,
        owner -> {
          int directory = owner.openRoot();
          for (Path segment : runtime)
            directory = owner.openDirectory(directory, segment.toString());
          Identity runIdentity = identity(held(directory), true, hostView);
          int app = owner.openDirectory(directory, "schubert-nk");
          Identity appIdentity = identity(held(app), true, hostView);
          require(runIdentity.device() == appIdentity.device());
          int entry = owner.openEntry(app, "startup-admission.lock");
          Path file = held(entry);
          Identity fileIdentity = identity(file, false, hostView);
          require(appIdentity.device() == fileIdentity.device());
          return operation.execute(
              new Snapshot(runIdentity, appIdentity, fileIdentity), file, owner);
        });
  }

  private void verify(Snapshot expected) throws IOException {
    withView(
        host,
        true,
        (actual, held, owner) -> {
          require(expected.equals(actual));
          return Boolean.TRUE;
        });
    withView(
        service,
        false,
        (actual, held, owner) -> {
          require(expected.equals(actual));
          return Boolean.TRUE;
        });
  }

  private Identity identity(Path held, boolean directory, boolean hostView) throws IOException {
    Map<String, Object> values = io.attributes(held);
    if (values == null
        || !(values.get("mode") instanceof Integer mode)
        || !(values.get("uid") instanceof Integer uid)
        || !(values.get("gid") instanceof Integer gid)
        || !(values.get("nlink") instanceof Integer links)
        || !(values.get("size") instanceof Long size)
        || !(values.get("dev") instanceof Long device)
        || !(values.get("ino") instanceof Long inode)) throw unavailable();
    if (directory) require(mode == 0x41ed && links >= 2 && size >= 0);
    else require(mode == 0x8180 && links == 1 && size == 0);
    require(uid == 0 && gid == 0);
    require("tmpfs".equals(io.filesystemType(held)));
    // Current retained host flags, never Java canonical FileStore.isReadOnly(). Private A may be
    // RO.
    if (hostView) require(!security.readOnlyFilesystem(held));
    require(security.accessAcl(held, 44).length == 0);
    return new Identity(mode, uid, gid, device, inode);
  }

  private static void require(boolean valid) throws StorageIoException {
    if (!valid) throw unavailable();
  }

  private static StorageIoException unavailable() {
    return new StorageIoException(StorageIoException.Reason.UNAVAILABLE);
  }

  @FunctionalInterface
  private interface ViewOperation<T> {
    T execute(Snapshot snapshot, Path heldFile, ViewOwner owner) throws IOException;
  }

  private static Path held(int descriptor) {
    return Path.of("/proc/self/fd/" + descriptor);
  }

  /** Private root observation owner only, not a general exported file capability. */
  static final class ViewOwner {
    private final DirectoryCalls calls;
    private final int[] descriptors;
    private final boolean[] secondaryFailures;
    private int count;
    private boolean closed;

    ViewOwner(DirectoryCalls calls, int capacity) {
      this.calls = Objects.requireNonNull(calls, "view directory calls");
      if (capacity < MINIMUM_PRIVATE_VIEW_CAPACITY)
        throw new IllegalArgumentException("positive private view capacity");
      descriptors = new int[capacity];
      secondaryFailures = new boolean[capacity];
    }

    // SSC308/VIEWFD001-008: guard before native IO, then only primitive work on valid new FD.
    int openRoot() throws StorageIoException {
      guard();
      int descriptor = calls.openRoot();
      if (descriptor < 0) throw unavailable();
      for (int index = 0; index < count; index++)
        if (descriptors[index] == descriptor) throw unavailable();
      descriptors[count++] = descriptor;
      return descriptor;
    }

    int openDirectory(int parent, String name) throws StorageIoException {
      Objects.requireNonNull(name, "view directory segment");
      guard();
      parent(parent);
      int descriptor = calls.openDirectory(parent, name);
      if (descriptor < 0) throw unavailable();
      for (int index = 0; index < count; index++)
        if (descriptors[index] == descriptor) throw unavailable();
      descriptors[count++] = descriptor;
      return descriptor;
    }

    int openEntry(int parent, String name) throws StorageIoException {
      Objects.requireNonNull(name, "view entry name");
      guard();
      parent(parent);
      int descriptor = calls.openEntry(parent, name);
      if (descriptor < 0) throw unavailable();
      for (int index = 0; index < count; index++)
        if (descriptors[index] == descriptor) throw unavailable();
      descriptors[count++] = descriptor;
      return descriptor;
    }

    private void guard() throws StorageIoException {
      if (closed || count == descriptors.length) throw unavailable();
    }

    private void parent(int descriptor) throws StorageIoException {
      for (int index = 0; index < count; index++) if (descriptors[index] == descriptor) return;
      throw unavailable();
    }

    void close() throws StorageIoException {
      if (closed) return;
      closed = true; // Consume all ownership once, even if a native close reports failure.
      for (int index = count - 1; index >= 0; index--) {
        try {
          calls.close(descriptors[index]);
        } catch (StorageIoException known) {
          throw closeAfterKnown(index - 1, known);
        } catch (RuntimeException | Error primary) {
          drain(index - 1);
          appendSecondary(primary);
          throw primary;
        }
      }
    }

    // Keep the original typed catch alive: the first unknown supersedes prior known IO only.
    private StorageIoException closeAfterKnown(int remaining, StorageIoException primary) {
      boolean multiple = false;
      for (int index = remaining; index >= 0; index--) {
        try {
          calls.close(descriptors[index]);
        } catch (StorageIoException secondary) {
          multiple = true;
        } catch (RuntimeException | Error unknown) {
          drain(index - 1);
          appendSecondary(unknown);
          throw unknown;
        }
      }
      // Every FD was attempted before this normalization can allocate or inspect suppression.
      return new StorageIoException(
          !multiple && primary.getSuppressed().length == 0
              ? primary.reason()
              : StorageIoException.Reason.UNAVAILABLE);
    }

    private void drain(int remaining) {
      for (int index = remaining; index >= 0; index--) {
        try {
          calls.close(descriptors[index]);
        } catch (StorageIoException | RuntimeException | Error secondary) {
          secondaryFailures[index] = true;
        }
      }
    }

    private void appendSecondary(Throwable primary) {
      for (int index = count - 1; index >= 0; index--)
        if (secondaryFailures[index]) primary.addSuppressed(unavailable());
    }
  }

  private record Identity(int mode, int uid, int gid, long device, long inode) {}

  private record Snapshot(Identity run, Identity app, Identity file) {}

  static final class NioIo implements Io {
    @Override
    public Map<String, Object> attributes(Path held) throws IOException {
      return Files.readAttributes(held, "unix:mode,uid,gid,nlink,size,dev,ino");
    }

    @Override
    public String filesystemType(Path held) throws IOException {
      return Files.getFileStore(held).type();
    }
  }
}

package dev.codex.schubert.nk.batch.platform;

import dev.codex.schubert.nk.storage.DirectoryCalls;
import dev.codex.schubert.nk.storage.InodeSecurityCalls;
import dev.codex.schubert.nk.storage.ResourceScope;
import dev.codex.schubert.nk.storage.StorageIoException;
import java.io.IOException;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import org.jspecify.annotations.NullMarked;
import org.jspecify.annotations.Nullable;

/**
 * Package-only genuine host cgroup namespace projection, not whole-process emptiness or authority.
 * NK-OPS-001/UI251/SS3415/343/SSC093100; BTERM001..008/MSTOP. Fixed enum leaf only. Narrow
 * extraction preserves all NOFOLLOW, ancestor identity, metadata, ACL and owner-close rules.
 */
@NullMarked
final class FixedUnitCgroupNamespace {
  private static final List<String> SEGMENTS = List.of("sys", "fs", "cgroup", "system.slice");

  @FunctionalInterface
  interface Context {
    void recheck() throws IOException;
  }

  interface Io {
    @Nullable Map<String, Object> attributes(Path held) throws IOException;

    @Nullable String filesystem(Path held) throws IOException;
  }

  private final Context context;
  private final DirectoryCalls host;
  private final InodeSecurityCalls security;
  private final Io io;

  FixedUnitCgroupNamespace(
      Context context, DirectoryCalls host, InodeSecurityCalls security, Io io) {
    this.context = Objects.requireNonNull(context, "root context");
    this.host = Objects.requireNonNull(host, "host view");
    this.security = Objects.requireNonNull(security, "inode security");
    this.io = Objects.requireNonNull(io, "inode IO");
  }

  void check() throws IOException {
    require(!Thread.currentThread().isInterrupted());
    context.recheck();
    require(security.effectiveUid() == 0);
    require(!Thread.currentThread().isInterrupted());
  }

  Snapshot observe(MaintenanceUnit unit) throws IOException {
    Objects.requireNonNull(unit, "fixed Unit");
    check();
    return ResourceScope.<Owner, Snapshot, StorageIoException>acquire(
        () -> new Owner(host),
        Owner::close,
        owner -> {
          var identities = new ArrayList<Identity>();
          int directory = owner.openRoot();
          identities.add(identity(directory, 0));
          for (int i = 0; i < SEGMENTS.size(); i++) {
            directory = owner.openDirectory(directory, SEGMENTS.get(i));
            identities.add(identity(directory, i + 1));
          }
          require(identities.get(1).device() == identities.get(2).device());
          require(identities.get(3).device() == identities.get(4).device());
          boolean present = true;
          int leaf = -1;
          try {
            leaf = owner.openDirectory(directory, unit.serviceName());
          } catch (StorageIoException failure) {
            if (failure.reason() != StorageIoException.Reason.MISSING) throw failure;
            present = false;
          }
          // BUG277/SSC308: only the open syscall's MISSING is absence; registration is primitive.
          if (present) {
            var child = identity(leaf, 4);
            require(child.device() == identities.get(4).device());
            identities.add(child);
          }
          for (int i = 0; i < identities.size(); i++) {
            require(identities.get(i).equals(identity(owner.descriptor(i), Math.min(i, 4))));
          }
          check();
          return new Snapshot(List.copyOf(identities), present);
        });
  }

  private Identity identity(int descriptor, int position) throws IOException {
    Path held = Path.of("/proc/self/fd/" + descriptor);
    var values = io.attributes(held);
    if (values == null
        || !(values.get("mode") instanceof Integer mode)
        || !(values.get("uid") instanceof Integer uid)
        || !(values.get("gid") instanceof Integer gid)
        || !(values.get("nlink") instanceof Integer links)
        || !(values.get("size") instanceof Long size)
        || !(values.get("dev") instanceof Long device)
        || !(values.get("ino") instanceof Long inode))
      throw new IOException("maintenance cgroup namespace unavailable");
    require((mode == 0x416d || mode == 0x41ed) && uid == 0 && gid == 0 && links >= 2 && size >= 0);
    require(device >= 0 && inode > 0);
    if (position > 0) require((position < 3 ? "sysfs" : "cgroup2").equals(io.filesystem(held)));
    require(security.accessAcl(held, 44).length == 0);
    return new Identity(mode, uid, gid, device, inode);
  }

  record Identity(int mode, int uid, int gid, long device, long inode) {}

  record Snapshot(List<Identity> identities, boolean present) {}

  private static void require(boolean valid) throws IOException {
    if (!valid) throw new IOException("maintenance cgroup namespace unavailable");
  }

  // SSC308/PT-OPS-CGROUPFD001-008: package-visible for independent primitive ownership tests.
  static final class Owner {
    private final DirectoryCalls calls;
    private final int[] descriptors = new int[6];
    private final boolean[] secondaryFailures = new boolean[6];
    private int count;
    private boolean closed;

    Owner(DirectoryCalls calls) {
      this.calls = Objects.requireNonNull(calls, "cgroup directory calls");
    }

    int openRoot() throws StorageIoException {
      guard();
      int descriptor = calls.openRoot();
      if (descriptor < 0) throw unavailable();
      for (int index = 0; index < count; index++)
        if (descriptors[index] == descriptor) throw unavailable();
      descriptors[count++] = descriptor;
      return descriptor;
    }

    int openDirectory(int parent, String name) throws StorageIoException {
      Objects.requireNonNull(name, "cgroup directory segment");
      guard();
      boolean held = false;
      for (int index = 0; index < count; index++) if (descriptors[index] == parent) held = true;
      if (!held) throw unavailable();
      int descriptor = calls.openDirectory(parent, name);
      if (descriptor < 0) throw unavailable();
      for (int index = 0; index < count; index++)
        if (descriptors[index] == descriptor) throw unavailable();
      descriptors[count++] = descriptor;
      return descriptor;
    }

    private void guard() throws StorageIoException {
      if (closed || count == descriptors.length) throw unavailable();
    }

    int descriptor(int position) {
      return descriptors[position];
    }

    void close() throws StorageIoException {
      if (closed) return;
      closed = true;
      for (int index = 0; index < count; index++) {
        try {
          calls.close(descriptors[index]);
        } catch (StorageIoException known) {
          throw closeAfterKnown(index + 1, known);
        } catch (RuntimeException | Error primary) {
          drain(index + 1);
          appendSecondary(primary);
          throw primary;
        }
      }
    }

    private StorageIoException closeAfterKnown(int remaining, StorageIoException primary) {
      boolean multiple = false;
      for (int index = remaining; index < count; index++) {
        try {
          calls.close(descriptors[index]);
        } catch (StorageIoException secondary) {
          multiple = true;
        } catch (RuntimeException | Error unknown) {
          drain(index + 1);
          appendSecondary(unknown);
          throw unknown;
        }
      }
      return new StorageIoException(
          !multiple && primary.getSuppressed().length == 0
              ? primary.reason()
              : StorageIoException.Reason.UNAVAILABLE);
    }

    private void drain(int remaining) {
      for (int index = remaining; index < count; index++) {
        try {
          calls.close(descriptors[index]);
        } catch (StorageIoException | RuntimeException | Error secondary) {
          secondaryFailures[index] = true;
        }
      }
    }

    private void appendSecondary(Throwable primary) {
      for (int index = 0; index < count; index++)
        if (secondaryFailures[index]) primary.addSuppressed(unavailable());
    }

    private static StorageIoException unavailable() {
      return new StorageIoException(StorageIoException.Reason.UNAVAILABLE);
    }
  }
}

package dev.codex.schubert.nk.batch.platform;

import dev.codex.schubert.nk.batch.file.CaddyPublicConfiguration;
import dev.codex.schubert.nk.bootstrap.ChildStartupContext;
import dev.codex.schubert.nk.bootstrap.FixedServiceIdentity;
import dev.codex.schubert.nk.storage.ResourceScope;
import java.io.IOException;
import java.io.InputStream;
import java.net.InetAddress;
import java.net.Proxy;
import java.net.URI;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.NoSuchFileException;
import java.nio.file.Path;
import java.util.Arrays;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import java.util.UUID;
import javax.net.ssl.HttpsURLConnection;
import org.jspecify.annotations.NullMarked;
import org.jspecify.annotations.Nullable;

/** Same-parent fixed Caddy daemon/validate/owned TLS login proof. SS342/SSC178/CADDY455. */
@NullMarked
public final class MorningCaddyReadiness {
  private static final int IPV4_ADDRESS_BYTES = 4;
  private static final int MAXIMUM_SOCKET_DIRECTORY_ENTRIES = 65536;
  private static final int SUCCESS_HTTP_STATUS = 200;

  /** SSC308/PT-CADDYSTREAM001-006: nullable HTTP body, never nullable common ownership. */
  static void closeLoginInput(ResourceScope.Acquire<InputStream, IOException> open)
      throws IOException {
    Objects.requireNonNull(open, "Caddy response stream source");
    InputStream absent = InputStream.nullInputStream();
    ResourceScope.<InputStream, Boolean, IOException>acquire(
        () -> {
          InputStream input = open.open();
          return input == null ? absent : input;
        },
        InputStream::close,
        ignored -> Boolean.TRUE);
  }

  private static final java.lang.String LITERAL_INVOCATIONID = "InvocationID";

  private static final java.lang.String LITERAL_MAINPID = "MainPID";

  private static final java.lang.String LITERAL_EXECMAINCODE = "ExecMainCode";

  private static final java.lang.String LITERAL_EXECSTARTPRE = "ExecStartPre";

  private static final java.lang.String LITERAL_EXECSTART = "ExecStart";

  @FunctionalInterface
  interface Guard {
    void check() throws IOException;
  }

  interface Io {
    Map<String, String> manager() throws IOException;

    ChildStartupContext.Observed actor(String invocation) throws IOException;

    Set<String> sockets(long pid) throws IOException;

    int login() throws IOException;
  }

  private final Guard guard;
  private final Io io;
  private final String invocation;
  private final long pid;
  private final ChildStartupContext.Observed captured;

  public static MorningCaddyReadiness create(
      RootStartupContext root, RootStartupContext.Snapshot morning, MorningParentBudget budget)
      throws IOException {
    return create(root, morning, budget, "");
  }

  /** SSC180: prior cold generation is a rejection constraint, never startup authority. */
  public static MorningCaddyReadiness create(
      RootStartupContext root,
      RootStartupContext.Snapshot morning,
      MorningParentBudget budget,
      String previousInvocation)
      throws IOException {
    Objects.requireNonNull(root);
    Objects.requireNonNull(morning);
    Objects.requireNonNull(budget);
    if (morning.service() != RootStartupContext.Service.MORNING) throw unavailable();
    return new MorningCaddyReadiness(
        () -> {
          budget.requireWithin();
          root.recheck(morning);
        },
        new NativeIo(root, morning),
        previousInvocation);
  }

  MorningCaddyReadiness(Guard guard, Io io) throws IOException {
    this(guard, io, "");
  }

  MorningCaddyReadiness(Guard guard, Io io, String previousInvocation) throws IOException {
    this.guard = Objects.requireNonNull(guard);
    this.io = Objects.requireNonNull(io);
    Objects.requireNonNull(previousInvocation);
    if (!previousInvocation.isEmpty() && !generation(previousInvocation)) throw unavailable();
    guard.check();
    var manager = Objects.requireNonNull(io.manager());
    profile(manager);
    invocation = Objects.requireNonNull(manager.get(LITERAL_INVOCATIONID));
    if (invocation.equals(previousInvocation)) throw unavailable();
    pid = Long.parseLong(Objects.requireNonNull(manager.get(LITERAL_MAINPID)));
    captured = Objects.requireNonNull(io.actor(invocation));
    if (captured.pid() != pid) throw unavailable();
    guard.check();
    if (!manager.equals(io.manager())) throw unavailable();
  }

  /** Manager-active is insufficient: verified CA/hostname HTTPS200 and same owned listener. */
  public boolean ready() throws IOException {
    guard.check();
    var before = Objects.requireNonNull(io.manager());
    profile(before);
    if (!invocation.equals(before.get(LITERAL_INVOCATIONID))
        || !Long.toString(pid).equals(before.get(LITERAL_MAINPID))
        || !captured.equals(io.actor(invocation))) throw unavailable();
    var sockets = Set.copyOf(Objects.requireNonNull(io.sockets(pid)));
    if (sockets.isEmpty()) return false;
    if (io.login() != SUCCESS_HTTP_STATUS) return false;
    guard.check();
    if (!captured.equals(io.actor(invocation)) || !before.equals(io.manager())) throw unavailable();
    var after = Set.copyOf(Objects.requireNonNull(io.sockets(pid)));
    guard.check();
    return sockets.stream().anyMatch(after::contains);
  }

  static void profile(Map<String, String> values) throws IOException {
    configuration(values);
    if (!"active".equals(values.get("ActiveState")) || !"running".equals(values.get("SubState")))
      throw unavailable();
    if (!"success".equals(values.get("Result"))
        || !"0".equals(values.get(LITERAL_EXECMAINCODE))
        || !"0".equals(values.get("ExecMainStatus"))
        || number(values.get("ExecMainStartTimestampMonotonic")).signum() == 0
        || number(values.get("ExecMainExitTimestampMonotonic")).signum() != 0) throw unavailable();
    String pidText = Objects.requireNonNull(values.get(LITERAL_MAINPID));
    if (!pidText.matches("[1-9][0-9]{0,9}")
        || Long.parseLong(pidText) < 2
        || Long.parseLong(pidText) > Integer.MAX_VALUE
        || !Objects.requireNonNull(values.get(LITERAL_INVOCATIONID))
            .matches("(?!0{32}$)[0-9a-f]{32}")) throw unavailable();
    String pre = Objects.requireNonNull(values.get(LITERAL_EXECSTARTPRE));
    if (!pre.matches(
            "\\{ path=/usr/bin/caddy ; argv\\[\\]=/usr/bin/caddy validate --config /etc/caddy/Caddyfile ; ignore_errors=no ; start_time=\\[[^\\]\\n]+\\] ; stop_time=\\[[^\\]\\n]+\\] ; pid=[1-9][0-9]{0,9} ; code=exited ; status=0(?:/0)? \\}")
        || pre.contains("[n/a]")) throw unavailable();
    String start = Objects.requireNonNull(values.get(LITERAL_EXECSTART));
    if (!start.matches(
        "\\{ path=/usr/bin/caddy ; argv\\[\\]=/usr/bin/caddy run --config /etc/caddy/Caddyfile ; ignore_errors=no ; start_time=\\[[^\\]\\n]+\\] ; stop_time=\\[n/a\\] ; pid="
            + pidText
            + " ; code=\\(null\\) ; status=0/0 \\}")) throw unavailable();
  }

  /** Same effective daemon configuration even before any ExecStartPre has run. */
  static void configuration(Map<String, String> values) throws IOException {
    Objects.requireNonNull(values);
    var fixed =
        Map.ofEntries(
            Map.entry("Id", "caddy.service"),
            Map.entry("LoadState", "loaded"),
            Map.entry("Job", ""),
            Map.entry("Type", "notify"),
            Map.entry("Restart", "no"),
            Map.entry("KillMode", "control-group"),
            Map.entry("SendSIGKILL", "no"),
            Map.entry("NoNewPrivileges", "yes"),
            Map.entry("CapabilityBoundingSet", ""),
            Map.entry("AmbientCapabilities", ""),
            Map.entry("User", "caddy"),
            Map.entry("Group", "caddy"),
            Map.entry("SupplementaryGroups", ""),
            Map.entry("TimeoutStartUSec", "30s"),
            Map.entry("TimeoutStopUSec", "30s"));
    var keys = new HashSet<>(fixed.keySet());
    keys.addAll(
        List.of(
            LITERAL_MAINPID,
            LITERAL_INVOCATIONID,
            LITERAL_EXECSTARTPRE,
            LITERAL_EXECSTART,
            "ActiveState",
            "SubState",
            "Result",
            LITERAL_EXECMAINCODE,
            "ExecMainStatus",
            "ExecMainStartTimestampMonotonic",
            "ExecMainExitTimestampMonotonic"));
    if (!values.keySet().equals(keys)) throw unavailable();
    for (var entry : fixed.entrySet())
      if (!entry.getValue().equals(values.get(entry.getKey()))) throw unavailable();
    String pre = Objects.requireNonNull(values.get(LITERAL_EXECSTARTPRE));
    if (!pre.startsWith(
            "{ path=/usr/bin/caddy ; argv[]=/usr/bin/caddy validate --config /etc/caddy/Caddyfile ; ignore_errors=no ; ")
        || pre.indexOf('}') != pre.length() - 1) throw unavailable();
    String start = Objects.requireNonNull(values.get(LITERAL_EXECSTART));
    if (!start.startsWith(
            "{ path=/usr/bin/caddy ; argv[]=/usr/bin/caddy run --config /etc/caddy/Caddyfile ; ignore_errors=no ; ")
        || start.indexOf('}') != start.length() - 1) throw unavailable();
  }

  public static void requireConfiguration(
      RootStartupContext root, RootStartupContext.Snapshot morning) throws IOException {
    coldInvocation(root, morning);
  }

  /** Continuous actual parent and whole-kernel observation, first boot or normal history. */
  public static String coldInvocation(RootStartupContext root, RootStartupContext.Snapshot morning)
      throws IOException {
    Objects.requireNonNull(root);
    Objects.requireNonNull(morning);
    root.recheck(morning);
    var io = new NativeIo(root, morning);
    var before = io.manager();
    String previous = cold(before);
    var terminal = MaintenanceUnitTermination.create(root, morning, MaintenanceUnit.CADDY);
    var first = terminal.quiescentObservation().orElseThrow(MorningCaddyReadiness::unavailable);
    var second = terminal.quiescentObservation().orElseThrow(MorningCaddyReadiness::unavailable);
    if (!previous.equals(first.manager().observedValues().get(10))
        || !first.manager().matches(second.manager())
        || first.leafPresent() != second.leafPresent()
        || !first.directories().equals(second.directories())
        || !before.equals(io.manager())) throw unavailable();
    root.recheck(morning);
    return previous;
  }

  static String cold(Map<String, String> before) throws IOException {
    configuration(before);
    if (!"inactive".equals(before.get("ActiveState"))
        || !"dead".equals(before.get("SubState"))
        || !"0".equals(before.get(LITERAL_MAINPID))
        || !"success".equals(before.get("Result"))
        || !"0".equals(before.get("ExecMainStatus"))) throw unavailable();
    String invocation = Objects.requireNonNull(before.get(LITERAL_INVOCATIONID));
    var start = number(before.get("ExecMainStartTimestampMonotonic"));
    var ended = number(before.get("ExecMainExitTimestampMonotonic"));
    String pre = Objects.requireNonNull(before.get(LITERAL_EXECSTARTPRE));
    String run = Objects.requireNonNull(before.get(LITERAL_EXECSTART));
    if (invocation.isEmpty()) {
      if (!"0".equals(before.get(LITERAL_EXECMAINCODE))
          || start.signum() != 0
          || ended.signum() != 0
          || !unused(pre, "validate")
          || !unused(run, "run")) throw unavailable();
    } else if (!generation(invocation)
        || !"1".equals(before.get(LITERAL_EXECMAINCODE))
        || start.signum() == 0
        || ended.compareTo(start) < 0
        || !((normal(pre, "validate") && normal(run, "run"))
            // SS342/SSC192: reload-cleared auxiliary data rejects the old generation only.
            // It is not evidence of validation, readiness, ownership, or normal outer close.
            || (unused(pre, "validate") && unused(run, "run")))) throw unavailable();
    return invocation;
  }

  private static boolean generation(String value) {
    return value.matches("(?!0{32}$)[0-9a-f]{32}");
  }

  private static java.math.BigInteger number(@Nullable String value) throws IOException {
    if (value == null || !value.matches("0|[1-9][0-9]{0,19}")) throw unavailable();
    var number = new java.math.BigInteger(value);
    if (number.compareTo(new java.math.BigInteger("18446744073709551615")) > 0) throw unavailable();
    return number;
  }

  private static boolean unused(String value, String operation) {
    return value.equals(
        "{ path=/usr/bin/caddy ; argv[]=/usr/bin/caddy "
            + operation
            + " --config /etc/caddy/Caddyfile ; ignore_errors=no ; start_time=[n/a] ; stop_time=[n/a] ; pid=0 ; code=(null) ; status=0/0 }");
  }

  private static boolean normal(String value, String operation) {
    var match =
        java.util.regex.Pattern.compile(
                "\\{ path=/usr/bin/caddy ; argv\\[\\]=/usr/bin/caddy "
                    + operation
                    + " --config /etc/caddy/Caddyfile ; ignore_errors=no ; start_time=\\[[^\\]\\n]+\\] ; stop_time=\\[[^\\]\\n]+\\] ; pid=([1-9][0-9]{0,9}) ; code=exited ; status=0(?:/0)? \\}")
            .matcher(value);
    if (!match.matches() || value.contains("[n/a]")) return false;
    // This mandatory capture participates in every successful match; no optional group exists.
    long process = Long.parseLong(Objects.requireNonNull(match.group(1)));
    return process >= 2 && process <= Integer.MAX_VALUE;
  }

  static Set<String> listeners(
      String table, Set<String> descriptors, String address, boolean ipv6) {
    Objects.requireNonNull(table);
    Objects.requireNonNull(descriptors);
    Objects.requireNonNull(address);
    var owned = new HashSet<String>();
    for (String line : table.split("\n")) {
      String[] fields = line.trim().split("\\s+");
      if (fields.length >= 10
          && fields[1].equals(address + ":D778")
          && fields[3].equals("0A")
          && fields[9].matches("[1-9][0-9]{0,19}")
          && descriptors.contains(fields[9])) owned.add(fields[9]);
    }
    return Set.copyOf(owned);
  }

  static String kernelAddress(byte[] address) {
    if (address.length != 4 && address.length != 16)
      throw new IllegalArgumentException("literal IP required");
    var text = new StringBuilder();
    for (int group = 0; group < address.length; group += 4)
      for (int index = group + 3; index >= group; index--)
        text.append(String.format(Locale.ROOT, "%02X", address[index] & 255));
    return text.toString();
  }

  private static IOException unavailable() {
    return new IOException("Caddy readiness unavailable");
  }

  private static final class NativeIo implements Io {
    private final RootStartupContext root;
    private final RootStartupContext.Snapshot morning;
    private final URI site;

    NativeIo(RootStartupContext root, RootStartupContext.Snapshot morning) throws IOException {
      this.root = root;
      this.morning = morning;
      site = CaddyPublicConfiguration.site(root, morning);
    }

    public Map<String, String> manager() throws IOException {
      byte[] bytes =
          new InspectorUnitProbe.NativeReader()
              .execute(
                  List.of(
                      "/usr/bin/systemctl",
                      "--system",
                      "--no-pager",
                      "--no-ask-password",
                      "show",
                      "--property=Id,LoadState,ActiveState,SubState,MainPID,InvocationID,Job,Type,Restart,KillMode,SendSIGKILL,NoNewPrivileges,CapabilityBoundingSet,AmbientCapabilities,User,Group,SupplementaryGroups,TimeoutStartUSec,TimeoutStopUSec,ExecStartPre,ExecStart,Result,ExecMainCode,ExecMainStatus,ExecMainStartTimestampMonotonic,ExecMainExitTimestampMonotonic",
                      "caddy.service"),
                  8192);
      if (bytes.length == 0 || bytes[bytes.length - 1] != '\n') throw unavailable();
      var values = new HashMap<String, String>();
      for (String line :
          new String(bytes, StandardCharsets.US_ASCII).stripTrailing().split("\n", -1)) {
        int separator = line.indexOf('=');
        if (separator < 1
            || values.putIfAbsent(line.substring(0, separator), line.substring(separator + 1))
                != null) throw unavailable();
      }
      return Map.copyOf(values);
    }

    public ChildStartupContext.Observed actor(String invocation) throws IOException {
      root.recheck(morning);
      var actor =
          new ChildStartupContext()
              .verifyCaddy(
                  UUID.fromString(morning.boot()),
                  invocation,
                  new FixedServiceIdentity().resolveCaddy());
      byte[] command =
          MorningServiceReadiness.NativeIo.read(
              Path.of("/proc", Long.toString(actor.pid()), "cmdline"), 16384);
      if (!Arrays.equals(
          command,
          "/usr/bin/caddy\0run\0--config\0/etc/caddy/Caddyfile\0"
              .getBytes(StandardCharsets.US_ASCII))) throw unavailable();
      root.recheck(morning);
      return actor;
    }

    public Set<String> sockets(long pid) throws IOException {
      var proc = Path.of("/proc", Long.toString(pid));
      var descriptors = new HashSet<String>();
      try (var entries = Files.newDirectoryStream(proc.resolve("fd"))) {
        int count = 0;
        for (Path entry : entries) {
          if (++count > MAXIMUM_SOCKET_DIRECTORY_ENTRIES) throw unavailable();
          try {
            String target = Files.readSymbolicLink(entry).toString();
            if (target.matches("socket:\\[[1-9][0-9]{0,19}\\]"))
              descriptors.add(target.substring(8, target.length() - 1));
          } catch (NoSuchFileException gone) {
            /* Never counts as owned evidence. */
          }
        }
      }
      byte[] literal = InetAddress.getByName(site.getHost()).getAddress();
      String family = literal.length == 4 ? "tcp" : "tcp6";
      var owned =
          new HashSet<>(
              listeners(
                  new String(
                      MorningServiceReadiness.NativeIo.read(
                          proc.resolve("net/" + family), 2_097_152),
                      StandardCharsets.US_ASCII),
                  descriptors,
                  kernelAddress(literal),
                  literal.length == 16));
      if (literal.length == IPV4_ADDRESS_BYTES) {
        byte[] mapped = new byte[16];
        mapped[10] = (byte) 255;
        mapped[11] = (byte) 255;
        System.arraycopy(literal, 0, mapped, 12, 4);
        owned.addAll(
            listeners(
                new String(
                    MorningServiceReadiness.NativeIo.read(proc.resolve("net/tcp6"), 2_097_152),
                    StandardCharsets.US_ASCII),
                descriptors,
                kernelAddress(mapped),
                true));
      }
      return Set.copyOf(owned);
    }

    public int login() throws IOException {
      var connection = (HttpsURLConnection) site.toURL().openConnection(Proxy.NO_PROXY);
      connection.setSSLSocketFactory(
          CaddyPublicConfiguration.tls(root, morning).getSocketFactory());
      connection.setInstanceFollowRedirects(false);
      connection.setUseCaches(false);
      connection.setConnectTimeout(1000);
      connection.setReadTimeout(1000);
      connection.setRequestMethod("GET");
      try {
        int status = connection.getResponseCode();
        closeLoginInput(
            () -> status >= 400 ? connection.getErrorStream() : connection.getInputStream());
        return status;
      } finally {
        connection.disconnect();
      }
    }
  }
}

package dev.codex.schubert.nk.batch.platform;

import dev.codex.schubert.nk.bootstrap.FixedServiceIdentity;
import dev.codex.schubert.nk.storage.ResourceScope;
import dev.codex.schubert.nk.storage.ServiceConfigFiles;
import java.io.IOException;
import java.net.HttpURLConnection;
import java.net.Proxy;
import java.net.URI;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.LinkOption;
import java.nio.file.NoSuchFileException;
import java.nio.file.Path;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import org.jspecify.annotations.NullMarked;

/**
 * Same captured Root-to-ordinary generation, owned loopback socket and signed information.
 * Observation only, never permit/intent retirement or parent completion authority. NK-OPS-001;
 * SYS002/004,OPS009/UI212/251/SS342/343 SSC164; PT-OPS-READY428001..006.
 */
@NullMarked
public final class MorningServiceReadiness {
  private static final int JSON_OPENING_DELIMITER_LENGTH = 1;
  private static final int MAXIMUM_SOCKET_DIRECTORY_ENTRIES = 65536;
  private static final int SUCCESS_HTTP_STATUS = 200;

  private static final java.lang.String LITERAL_SERVICE_OBSERVATION_UNAVAILABLE =
      "service observation unavailable";

  @FunctionalInterface
  interface Guard {
    void check() throws IOException;
  }

  interface Io {
    byte[] status() throws IOException;

    byte[] command() throws IOException;

    Set<String> sockets() throws IOException;

    Response get(String path) throws IOException;
  }

  record Response(int status, String body) {
    Response {
      Objects.requireNonNull(body);
    }
  }

  private final Guard guard;
  private final Io io;
  private final FixedServiceIdentity.Value identity;
  private final String main;
  private final String information;

  public static MorningServiceReadiness create(
      RootStartupContext root,
      RootStartupContext.Snapshot morning,
      RootStartupContext.Snapshot captured,
      Map<String, String> information)
      throws IOException {
    Objects.requireNonNull(root);
    Objects.requireNonNull(morning);
    Objects.requireNonNull(captured);
    var service =
        switch (captured.service()) {
          case API -> ServiceConfigFiles.Service.API;
          case WEB -> ServiceConfigFiles.Service.WEB;
          default -> throw new IllegalArgumentException("fixed service required");
        };
    root.recheckServiceGeneration(morning, captured);
    return new MorningServiceReadiness(
        () -> root.recheckServiceGeneration(morning, captured),
        new NativeIo(captured.pid(), service == ServiceConfigFiles.Service.API ? 8091 : 8081),
        new FixedServiceIdentity().resolve(service),
        service == ServiceConfigFiles.Service.API
            ? "dev.codex.schubert.nk.api.bootstrap.ApiProcessMain"
            : "dev.codex.schubert.nk.web.bootstrap.WebProcessMain",
        information);
  }

  MorningServiceReadiness(
      Guard guard,
      Io io,
      FixedServiceIdentity.Value identity,
      String main,
      Map<String, String> information) {
    this.guard = Objects.requireNonNull(guard);
    this.io = Objects.requireNonNull(io);
    this.identity = Objects.requireNonNull(identity);
    this.main = Objects.requireNonNull(main);
    var keys = List.of("commit", "app", "config", "schema", "protocol");
    if (!Objects.requireNonNull(information).keySet().equals(Set.copyOf(keys)))
      throw new IllegalArgumentException("invalid public information");
    var json = new StringBuilder("{");
    for (String key : keys) {
      String value = Objects.requireNonNull(information.get(key));
      if (!(key.equals("commit")
          ? value.matches("[0-9a-f]{40}")
          : value.matches("[A-Za-z0-9][A-Za-z0-9._+\\-]{0,127}")))
        throw new IllegalArgumentException("invalid public information");
      if (json.length() > JSON_OPENING_DELIMITER_LENGTH) json.append(',');
      json.append('"').append(key).append("\":\"").append(value).append('"');
    }
    this.information = json.append('}').toString();
  }

  /** Not-yet-ready is false; IO/identity uncertainty never becomes success. */
  public boolean ready() throws IOException {
    guard.check();
    if (!ordinary()) return false;
    var before = Set.copyOf(Objects.requireNonNull(io.sockets()));
    if (before.isEmpty()) return false;
    var health = Objects.requireNonNull(io.get("/actuator/health/readiness"));
    var info = Objects.requireNonNull(io.get("/actuator/info"));
    if (health.status() != 200
        || !health.body().equals("{\"status\":\"UP\"}")
        || info.status() != 200
        || !info.body().equals(information)) return false;
    guard.check();
    if (!ordinary()) return false;
    var after = Set.copyOf(Objects.requireNonNull(io.sockets()));
    guard.check();
    return before.stream().anyMatch(after::contains);
  }

  private boolean ordinary() throws IOException {
    String status = ascii(Objects.requireNonNull(io.status()), 16384);
    var fields = new HashMap<String, String>();
    for (String line : status.split("\n")) {
      int colon = line.indexOf(':');
      if (colon > 0
          && fields.put(line.substring(0, colon), line.substring(colon + 1).trim()) != null)
        return false;
    }
    String uid = String.join(" ", Collections.nCopies(4, Long.toString(identity.uid())));
    String gid = String.join(" ", Collections.nCopies(4, Long.toString(identity.gid())));
    String groups =
        identity.groups().stream()
            .map(Object::toString)
            .collect(java.util.stream.Collectors.joining(" "));
    if (!uid.equals(normal(fields.getOrDefault("Uid", "")))
        || !gid.equals(normal(fields.getOrDefault("Gid", "")))
        || !groups.equals(normal(fields.getOrDefault("Groups", "")))
        || !"1".equals(fields.get("NoNewPrivs"))) return false;
    for (String cap : List.of("CapInh", "CapPrm", "CapEff", "CapBnd", "CapAmb"))
      if (!"0000000000000000".equals(fields.get(cap))) return false;
    byte[] command = Objects.requireNonNull(io.command());
    try {
      if (command.length == 0 || command.length > 16384 || command[command.length - 1] != 0)
        return false;
      String text = new String(command, StandardCharsets.US_ASCII);
      return Arrays.stream(text.split("\u0000", -1)).filter(main::equals).count() == 1;
    } finally {
      Arrays.fill(command, (byte) 0);
    }
  }

  private static String normal(String value) {
    return value.trim().replaceAll("\\s+", " ");
  }

  private static String ascii(byte[] bytes, int maximum) throws IOException {
    if (bytes.length > maximum) throw new IOException(LITERAL_SERVICE_OBSERVATION_UNAVAILABLE);
    for (byte value : bytes)
      if (value < 0 || value == 0) throw new IOException(LITERAL_SERVICE_OBSERVATION_UNAVAILABLE);
    return new String(bytes, StandardCharsets.US_ASCII);
  }

  static Set<String> listeners(String table, Set<String> descriptors, int port, boolean ipv6) {
    Objects.requireNonNull(table);
    Objects.requireNonNull(descriptors);
    String address =
        (ipv6 ? "0000000000000000FFFF00000100007F:" : "0100007F:")
            + String.format(Locale.ROOT, "%04X", port);
    var owned = new HashSet<String>();
    for (String line : table.split("\n")) {
      String[] fields = line.trim().split("\\s+");
      if (fields.length >= 10
          && fields[1].equals(address)
          && fields[3].equals("0A")
          && fields[9].matches("[1-9][0-9]{0,19}")
          && descriptors.contains(fields[9])) owned.add(fields[9]);
    }
    return Set.copyOf(owned);
  }

  static final class NativeIo implements Io {
    private final Path proc;
    private final int port;

    NativeIo(long pid, int port) {
      if (pid < 2 || pid > Integer.MAX_VALUE || (port != 8091 && port != 8081))
        throw new IllegalArgumentException("fixed service required");
      this.proc = Path.of("/proc", Long.toString(pid));
      this.port = port;
    }

    public byte[] status() throws IOException {
      return read(proc.resolve("status"), 16384);
    }

    public byte[] command() throws IOException {
      return read(proc.resolve("cmdline"), 16384);
    }

    static byte[] read(Path path, int limit) throws IOException {
      return ResourceScope.acquire(
          () -> Files.newInputStream(path, LinkOption.NOFOLLOW_LINKS),
          java.io.InputStream::close,
          input -> {
            byte[] bytes = input.readNBytes(limit + 1);
            if (bytes.length > limit)
              throw new IOException(LITERAL_SERVICE_OBSERVATION_UNAVAILABLE);
            return bytes;
          });
    }

    public Set<String> sockets() throws IOException {
      var descriptors = new HashSet<String>();
      try (var entries = Files.newDirectoryStream(proc.resolve("fd"))) {
        int count = 0;
        for (Path entry : entries) {
          if (++count > MAXIMUM_SOCKET_DIRECTORY_ENTRIES)
            throw new IOException(LITERAL_SERVICE_OBSERVATION_UNAVAILABLE);
          try {
            String target = Files.readSymbolicLink(entry).toString();
            if (target.matches("socket:\\[[1-9][0-9]{0,19}\\]"))
              descriptors.add(target.substring(8, target.length() - 1));
          } catch (NoSuchFileException gone) {
            /* Kernel FD closed; cannot become owned evidence. */
          }
        }
      }
      var owned =
          new HashSet<>(
              listeners(
                  ascii(read(proc.resolve("net/tcp"), 2_097_152), 2_097_152),
                  descriptors,
                  port,
                  false));
      owned.addAll(
          listeners(
              ascii(read(proc.resolve("net/tcp6"), 2_097_152), 2_097_152),
              descriptors,
              port,
              true));
      return Set.copyOf(owned);
    }

    public Response get(String path) throws IOException {
      if (!Set.of("/actuator/health/readiness", "/actuator/info").contains(path))
        throw new IllegalArgumentException("fixed management path required");
      var connection =
          (HttpURLConnection)
              URI.create("http://127.0.0.1:" + port + path).toURL().openConnection(Proxy.NO_PROXY);
      try {
        connection.setInstanceFollowRedirects(false);
        connection.setConnectTimeout(500);
        connection.setReadTimeout(500);
        int status = connection.getResponseCode();
        if (status != SUCCESS_HTTP_STATUS) return new Response(status, "");
        return ResourceScope.acquire(
            connection::getInputStream,
            java.io.InputStream::close,
            input -> new Response(status, ascii(input.readNBytes(4097), 4096)));
      } finally {
        connection.disconnect();
      }
    }
  }
}
